// Where everything stands on each world's battlefield, as fractions of the scene (left, top, width, height).
// Generated by scripts/story_assets.py from the supplied battlefield paintings: do not edit by hand.

export interface Box {
	x: number;
	y: number;
	w: number;
	h: number;
}

export interface Field {
	/** Width over height of the painting. */
	ar: number;
	boss: Box;
	minA: Box;
	minB: Box;
	/** Where the hero's feet stand. */
	hero: { x: number; y: number };
	hearts: Box;
	panel: Box;
	dock: Box;
}

const box = (x: number, y: number, w: number, h: number): Box => ({ x, y, w, h });

